"""Replacement reels for 14 to 24 November 2026.

Weak single-slide reels (Sanskrit words, lesser-known verses) are swapped for
multi-slide reels on mantras and gods, which performed best in Metricool.
"""

Q_MANTRA = ("Which mantra should we explain next?", "Welches Mantra sollen wir als Nächstes erklären?")
Q_GOD = ("Which god should we explain next?", "Welchen Gott sollen wir als Nächstes erklären?")


def mantra(deva, translit, hook, words, says_head, says, where_label, where_head, where, end_deva, end_head, end_translit, cover="bordeaux"):
    return [
        {"bg": cover, "label": "Mantra meaning", "blocks": [("deva", deva), ("head", hook), ("translit", translit)]},
        {"bg": "cream", "label": "Word by word", "blocks": [("head", f"{len(words)} parts" if len(words) > 1 else "One line"), ("rule",), ("table", words)]},
        {"bg": "dark", "label": "What it says", "blocks": [("head", says_head), ("body", says)]},
        {"bg": "sand", "label": where_label, "blocks": [("head", where_head), ("body", where)]},
        {"bg": "darkest", "label": "Chant it", "center": True, "blocks": [("deva", end_deva), ("head", end_head), ("translit", end_translit), ("body", Q_MANTRA[0])]},
    ]


def god(deva, translit, hook, who_label, who_head, who, signs_label, signs_head, signs, story_head, story, mantra_deva, mantra_head, mantra_translit, cover="bordeaux"):
    return [
        {"bg": cover, "label": "Who is...?", "blocks": [("deva", deva), ("head", hook), ("translit", translit)]},
        {"bg": "cream", "label": who_label, "blocks": [("head", who_head), ("body", who)]},
        {"bg": "dark", "label": signs_label, "blocks": [("head", signs_head), ("rule",), ("table", signs)]},
        {"bg": "sand", "label": "The story", "blocks": [("head", story_head), ("body", story)]},
        {"bg": "darkest", "label": "The mantra", "center": True, "blocks": [("deva", mantra_deva), ("head", mantra_head), ("translit", mantra_translit), ("body", Q_GOD[0])]},
    ]


def caption(en, de, question, tags):
    return f"🇬🇧 {en}\n\n{question[0]}\n\n🇩🇪 {de}\n\n{question[1]}\n\n{tags}"


